    /* operation-cookie-param-crlf-fails-closed (canonical scenario 6): the
     * deletePet `api_key` cookie param is interpolated straight into the
     * Cookie request header. A value carrying CR/LF (or any control char)
     * would smuggle in extra headers, so the generated op validates every
     * assembled cookie value against the RFC 6265 cookie-value grammar and
     * fails closed with an ArgumentError BEFORE any request is sent — mirroring
     * the auth-cookie validation path. */
    test(
      'bhv operations 029 deletePet cookie param with CR/LF fails closed with RFC 6265 error',
      () async {
        final config = ConfigurationBuilder()
            .baseUrl('http://localhost:1')
            .build();
        final api = PetApi(apiClient: DefaultApiClient(), config: config);

        await expectLater(
          api.deletePet(
            1,
            const DeletePetOptions(apiKey: 'sess\r\nInjected: yes'),
          ),
          throwsA(isA<ArgumentError>()),
        );

        // A control character (not just CR/LF) is rejected the same way.
        await expectLater(
          api.deletePet(1, const DeletePetOptions(apiKey: 'sess\x00ion')),
          throwsA(isA<ArgumentError>()),
        );
      },
    );

