      () async {
        for (final sample in <List<Object>>[
          [
            <int>[0x68, 0x69],
            'aGk%3D',
            'aGk=',
          ],
          [
            <int>[0xFB, 0xFF],
            '%2B%2F8%3D',
            '+/8=',
          ],
        ]) {
          final bytes = Uint8List.fromList(sample[0] as List<int>);
          final wantQuery = sample[1] as String;
          final wantHeader = sample[2] as String;
          String? capturedQuery;
          String? capturedHeader;
          final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
          server.listen((request) {
            capturedQuery = request.uri.query;
            capturedHeader = request.headers.value('x-fingerprint');
            request.response
              ..statusCode = 200
              ..headers.contentType = ContentType.json
              ..write('{"id":5,"name":"Rex","photoUrls":[]}')
              ..close();
          });

          try {
            final config = ConfigurationBuilder()
                .baseUrl('http://localhost:${server.port}')
                .build();
            final api = PetApi(apiClient: DefaultApiClient(), config: config);

            await api.getPetTag(
              5,
              'cute',
              GetPetTagOptions(fingerprint: bytes, xFingerprint: bytes),
            );

            expect(
              capturedQuery,
              contains('fingerprint=$wantQuery'),
              reason: wantHeader,
            );
            expect(capturedHeader, equals(wantHeader), reason: wantHeader);
          } finally {
            await server.close();
          }
        }
      },
    );

    /* required-string-empty-rejected: for a REQUIRED string param, an empty
     * string "" is treated as "absent" (parity with go/rust/swift/elixir),
     * so the call must fail-fast with an ArgumentError rather than sending an
     * empty value on the wire. getPetByName's `category` is a required string
     * query param carried on the required Options object. */
    test(
      'bhv operations 051 getPetByName rejects a dot segment before dispatch',
      () async {
        final config = ConfigurationBuilder()
            .baseUrl('http://localhost:1')
            .build();
        final api = PetApi(apiClient: DefaultApiClient(), config: config);

        for (final name in ['.', '..']) {
          await expectLater(
            api.getPetByName(
              name,
              const GetPetByNameOptions(category: 'c', xCorrelationId: 'c-1'),
            ),
            throwsA(isA<ArgumentError>()),
            reason: name,
          );
        }
      },
    );

    test(
      'bhv operations 052 getPetByName throws when the required path parameter is empty',
      () async {
        final config = ConfigurationBuilder()
            .baseUrl('http://localhost:1')
            .build();
        final api = PetApi(apiClient: DefaultApiClient(), config: config);

        await expectLater(
          api.getPetByName(
            '',
            const GetPetByNameOptions(category: 'c', xCorrelationId: 'c-1'),
          ),
          throwsA(
            isA<ArgumentError>().having(
              (e) => e.message,
              'message',
              "Missing the required parameter 'name' when calling PetApi.getPetByName",
            ),
          ),
        );
      },
    );

    test(
      'bhv operations 064 getPetByName keeps a name that only contains dots',
      () async {
        String? capturedPath;
        final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
        server.listen((request) {
          capturedPath = request.uri.path;
          request.response
            ..statusCode = 200
            ..headers.contentType = ContentType.json
            ..write('{"id":1,"name":"...","photoUrls":[]}')
            ..close();
        });

        try {
          final config = ConfigurationBuilder()
              .baseUrl('http://localhost:${server.port}')
              .build();
