          final pet = await api.getPetByName(
            '...',
            const GetPetByNameOptions(category: 'c', xCorrelationId: 'c-1'),
          );

          expect(capturedPath, equals('/pet/byName/...'));
          expect(pet.name, equals('...'));
        } finally {
          await server.close();
        }
      },
    );

    test(
      'bhv operations 049 getPetByName rejects empty-string required category',
      () async {
        final config = ConfigurationBuilder()
            .baseUrl('http://localhost:1')
            .build();
        final api = PetApi(apiClient: DefaultApiClient(), config: config);

        await expectLater(
