  group('format: date parameters', () {
    /* Dart has no date-only type, so a `format: date` value is a DateTime.
     * A matrix-style date path param and each item of a date-array query
     * param must still go out as YYYY-MM-DD, never as a full date-time. */
    test(
      'bhv operations 057 getPetSummary sends the date path param and date array as dates',
      () async {
        String? capturedPath;
        String? capturedQuery;
        String? capturedCookie;
        final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
        server.listen((request) {
          capturedPath = request.uri.path;
          capturedQuery = request.uri.query;
          capturedCookie = request.headers.value('cookie');
          request.response
            ..statusCode = 200
            ..headers.contentType = ContentType.text
            ..write('hello')
            ..close();
        });

        try {
          final config = ConfigurationBuilder()
              .baseUrl('http://localhost:${server.port}')
              .build();
          final api = PetApi(apiClient: DefaultApiClient(), config: config);

          final result = await api.getPetSummary(
            1,
            DateTime.utc(2024, 1, 15),
            GetPetSummaryOptions(
              session: 'abc',
              days: [DateTime.utc(2024, 1, 15), DateTime.utc(2024, 2, 1)],
            ),
          );

          expect(result, equals('hello'));
          expect(capturedPath, equals('/pet/1/summary/;asOf=2024-01-15'));
          expect(capturedQuery, equals('days=2024-01-15&days=2024-02-01'));
          expect(capturedCookie, equals('session=abc'));
        } finally {
          await server.close();
        }
      },
    );
  });

  group('cookie parameters (F840)', () {
    /* A value made only of RFC 6265 cookie-octets goes out raw; any other
     * value fails with an ArgumentError before a request is sent. */
    Future<(String?, Object?)> callWithSession(String session) async {
      String? capturedCookie;
      final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
      server.listen((request) {
        capturedCookie = request.headers.value('cookie');
        request.response
          ..statusCode = 200
          ..headers.contentType = ContentType.text
          ..write('hello')
          ..close();
      });
      try {
        final config = ConfigurationBuilder()
            .baseUrl('http://localhost:${server.port}')
            .build();
        final api = PetApi(apiClient: DefaultApiClient(), config: config);
        try {
          await api.getPetSummary(
            1,
            DateTime.utc(2024, 1, 15),
            GetPetSummaryOptions(session: session),
          );
        } on Object catch (e) {
          return (capturedCookie, e);
        }
        return (capturedCookie, null);
      } finally {
        await server.close();
      }
    }

    test(
      'bhv operations 030 a value of legal cookie-octets is sent raw',
      () async {
        final (cookie, error) = await callWithSession('a=b/c%20d');

        expect(error, isNull);
        expect(cookie, equals('session=a=b/c%20d'));
      },
    );

    test(
      'bhv langdart 001 a value with a space, semicolon, comma, quote or backslash fails before sending',
      () async {
        for (final value in ['a b', 'a;b', 'a,b', 'a"b', r'a\b', 'caf\u00e9']) {
          final (cookie, error) = await callWithSession(value);

          expect(error, isA<ArgumentError>(), reason: value);
          expect(cookie, isNull, reason: value);
        }
      },
    );
  });

  group('operation doc comments', () {
    final source = File(
      '${Directory.current.path}/lib/src/api/pet_api.dart',
    ).readAsStringSync();

    /* A deprecated operation carries @Deprecated on every public variant, a
     * deprecated model carries it on the class and a deprecated parameter on
     * its Options field. */
    test(
      'bhv operations 033 deprecation markers sit on every variant of a deprecated operation',
      () {
        expect(
          source,
          contains(
            "  @Deprecated('This operation is deprecated.')\n"
            '  @override\n'
            '  Future<List<Pet>> findPetsByStatus(',
          ),
        );
        expect(
          source,
          contains(
            "  @Deprecated('This operation is deprecated.')\n"
            '  @override\n'
            '  Future<ApiResult<List<Pet>>> findPetsByStatusWithHttpInfo(',
          ),
        );
        expect(
          source,
          contains(
            "  @Deprecated('This operation is deprecated.')\n"
            '  @override\n'
            '  Future<Pet> getPetById(',
          ),
        );
      },
    );

    test(
      'bhv operations 032 deprecation markers sit on a deprecated model and parameter',
      () {
        final tag = File(
          '${Directory.current.path}/lib/src/models/tag.dart',
        ).readAsStringSync();
        expect(
          tag,
          contains("@Deprecated('This schema is deprecated.')\nclass Tag {"),
        );
        final options = File(
          '${Directory.current.path}/lib/src/api/options/find_pets_by_status_options.dart',
        ).readAsStringSync();
        expect(
          options,
          contains(
            "@Deprecated('This parameter is deprecated.')\n  final String? status;",
          ),
        );
      },
    );

    /* The `options` argument is documented on every operation that takes
     * it, by what the Options class carries (no authenticator: F857). */
    test('bhv operations 082 document the options argument by what it carries', () {
      expect(
        source,
        contains(
          '  /// `options` options carrying the per-call timeout, headers and retry budget\n'
          '  /// Throws `BadRequestException` on HTTP 400.\n'
          '  @override\n'
          '  Future<Pet> addPet(',
        ),
      );
      expect(
        source,
        contains(
          '  /// `options` options for query, header, form, and cookie parameters\n'
          '  /// Throws `BadRequestException` on HTTP 400.\n'
          '  @override\n'
          '  Future<void> deletePet(',
        ),
      );
      expect(
        source,
        contains(
          '  /// `days` Extra dates to summarise\n'
          '  /// `options` options for query, header, form, and cookie parameters\n'
          '  /// Throws `NotFoundException` on HTTP 404.\n'
          '  @override\n'
          '  Future<String> getPetSummary(',
        ),
      );
    });

    /* Spec prose reaches the doc comment as written: no HTML entity and no
     * string-literal backslash before a quote. */
    test('bhv langdart 002 render spec prose verbatim', () {
      expect(
        source,
        contains("  /// Get a <plain> \"text\" summary & it's short\n"),
      );
      expect(
        source,
        contains("  /// `session` Session token: \"a<b>\" & it's required\n"),
      );
      final docLines = source
          .split('\n')
          .where((line) => line.trimLeft().startsWith('///'));
      for (final line in docLines) {
        expect(
          line,
          isNot(matches(RegExp(r'&(#[0-9]+|#x[0-9a-fA-F]+|[a-zA-Z]+);'))),
        );
        expect(line, isNot(contains(r'\"')));
      }
    });
  });

  group('calls the type system rejects are refused at run time', () {
    /* The analyzer already refuses these at compile time; a dynamic call
     * reaches the same check the VM makes, so each refusal is observable and
     * nothing is sent. */
    Matcher refusedNaming(String name) => throwsA(
      isA<Error>().having((e) => e.toString(), 'message', contains(name)),
    );

    final api = PetApi(
      apiClient: DefaultApiClient(),
      config: ConfigurationBuilder().baseUrl('http://127.0.0.1:1').build(),
    );

    test(
      'bhv operations 125 a nil required query option is refused and names the option',
      () {
        expect(
          () => Function.apply(GetPetByNameOptions.new, [], {
            #category: null,
            #xCorrelationId: 'x',
          }),
          refusedNaming('category'),
        );
      },
    );

    test(
      'bhv operations 132 a missing required option names the first required field',
      () {
        expect(
          () => Function.apply(GetPetByNameOptions.new, [], {
            #xCorrelationId: 'x',
          }),
          refusedNaming('category'),
        );
      },
    );

    test(
      'bhv operations 164 a nil required parameter is refused before any request is sent',
      () async {
        await expectLater(
          () => (api as dynamic).getPetByName(null, null),
          throwsA(isA<TypeError>()),
        );
      },
    );

    test(
      'bhv misc 012 a nil required argument is refused and names that argument',
      () {
        expect(
          () => (api as dynamic).getPetTag(1, null, null),
          refusedNaming('tagName'),
        );
      },
    );

    test(
      'bhv misc 010 a call that omits the options of an operation with required fields is refused',
      () {
        expect(
          () => Function.apply((api as dynamic).addPetPhotos as Function, [7]),
          throwsA(isA<NoSuchMethodError>()),
        );
      },
    );

    test(
      'bhv misc 051 an option the operation does not declare is refused rather than ignored',
      () {
        expect(
          () => Function.apply(GetPetByNameOptions.new, [], {
            #category: 'c',
            #xCorrelationId: 'x',
            #bogusOption: 1,
          }),
          throwsA(isA<NoSuchMethodError>()),
        );
      },
    );

    test(
      'bhv misc 075 a credential keyed to a scheme the API does not declare is refused when the client is built',
      () {
        expect(
          () => Function.apply(Client.new, [], {
            #undeclaredScheme: BearerAuthenticator(host: 'h', token: 't'),
          }),
          throwsA(isA<NoSuchMethodError>()),
        );
      },
    );

    test(
      'bhv misc 149 copying a model with an attribute it does not declare is refused and names it',
      () {
        final pet = Pet(name: 'Fido', photoUrls: <String>{'a'});
        expect(
          () => (pet as dynamic).copyWith(bogusAttribute: 1),
          refusedNaming('bogusAttribute'),
        );
      },
    );

    test('bhv models 014 a built model has no way to reassign a property', () {
      final pet = Pet(name: 'Fido', photoUrls: <String>{'a'});
      expect(
        () => (pet as dynamic).name = 'Rex',
        throwsA(isA<NoSuchMethodError>()),
      );
    });

    test(
      'bhv options 063 a built per-call options object has no way to change a field',
      () {
        const options = GetPetByNameOptions(category: 'c', xCorrelationId: 'x');
        expect(
          () => (options as dynamic).timeout = 5,
          throwsA(isA<NoSuchMethodError>()),
        );
      },
    );

    test(
      'bhv servers 020 a per-operation server variable value outside its enum is refused',
      () {
        expect(
          () => Function.apply(GetStagingPetInfoServerStagingServer.new, [
            'bogus',
            GetStagingPetInfoServerVersion.V2,
          ]),
          throwsA(isA<TypeError>()),
        );
      },
    );

    test(
      'bhv misc 260 nil for a server variable is refused instead of being substituted',
      () {
        expect(
          () => (server1 as dynamic).url({'environment': null}),
          throwsA(isA<TypeError>()),
        );
        expect(
          () => Function.apply(GetStagingPetInfoServerStagingServer.new, [
            null,
            GetStagingPetInfoServerVersion.V2,
          ]),
          throwsA(isA<TypeError>()),
        );
      },
    );
  });

